import React, { useState, useEffect } from 'react';
import { getMyJournals, createJournal, deleteJournal, updateJournal, getFriends, searchUsers, addFriend } from '../services/api';
import { useNavigate } from 'react-router-dom';

function MyProfile({ user }) {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('journals');
  const [journals, setJournals] = useState([]);
  const [friends, setFriends] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [journalForm, setJournalForm] = useState({ title: '', content: '', is_public: false });

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    loadData();
  }, [user, activeTab]);

  const loadData = async () => {
    try {
      if (activeTab === 'journals') {
        const data = await getMyJournals();
        setJournals(data);
      } else if (activeTab === 'friends') {
        const data = await getFriends();
        setFriends(data);
      }
    } catch (error) {
      console.error('Error:', error);
    }
  };

  const handleCreateJournal = async (e) => {
    e.preventDefault();
    try {
      await createJournal(journalForm);
      setShowForm(false);
      setJournalForm({ title: '', content: '', is_public: false });
      loadData();
    } catch (error) {
      alert('Failed to create journal');
    }
  };

  const handleDeleteJournal = async (id) => {
    if (window.confirm('Delete this journal?')) {
      try {
        await deleteJournal(id);
        loadData();
      } catch (error) {
        alert('Failed to delete');
      }
    }
  };

  const handleTogglePublic = async (journal) => {
    try {
      await updateJournal(journal.id, { is_public: !journal.is_public });
      loadData();
    } catch (error) {
      alert('Failed to update');
    }
  };

  if (!user) return null;

  return (
    <div className="container">
      <div style={{ background: 'white', borderRadius: '25px', padding: '3rem' }}>
        <h1 style={{ color: '#7F7FD5' }}>{user.full_name || user.username}</h1>
        
        <div style={{ display: 'flex', gap: '1rem', borderBottom: '2px solid #eee', marginTop: '2rem' }}>
          <button onClick={() => setActiveTab('journals')} style={{
            background: 'none', border: 'none', padding: '1rem', cursor: 'pointer',
            borderBottom: activeTab === 'journals' ? '3px solid #7F7FD5' : 'none',
            color: activeTab === 'journals' ? '#7F7FD5' : '#999', fontWeight: '600'
          }}>
            My Journals
          </button>
          <button onClick={() => setActiveTab('friends')} style={{
            background: 'none', border: 'none', padding: '1rem', cursor: 'pointer',
            borderBottom: activeTab === 'friends' ? '3px solid #7F7FD5' : 'none',
            color: activeTab === 'friends' ? '#7F7FD5' : '#999', fontWeight: '600'
          }}>
            Friends
          </button>
        </div>

        {activeTab === 'journals' && (
          <div>
            <button onClick={() => setShowForm(true)} className="submit-btn" style={{ marginTop: '1rem' }}>
              + New Journal
            </button>
            {journals.map(journal => (
              <div key={journal.id} style={{ background: '#f8f9fa', padding: '1rem', borderRadius: '10px', marginTop: '1rem' }}>
                <h3>{journal.title}</h3>
                <p>{journal.content}</p>
                <button onClick={() => handleTogglePublic(journal)}>
                  {journal.is_public ? '🌐 Public' : '🔒 Private'}
                </button>
                <button onClick={() => handleDeleteJournal(journal.id)} style={{ marginLeft: '0.5rem', background: '#e74c3c', color: 'white', border: 'none', padding: '0.5rem', borderRadius: '5px', cursor: 'pointer' }}>
                  Delete
                </button>
              </div>
            ))}
          </div>
        )}

        {activeTab === 'friends' && (
          <div>
            {friends.map(friend => (
              <div key={friend.id} style={{ padding: '1rem', background: '#f8f9fa', borderRadius: '10px', marginTop: '1rem' }}>
                {friend.username}
              </div>
            ))}
          </div>
        )}
      </div>

      {showForm && (
        <div style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center',
          justifyContent: 'center', zIndex: 9999
        }}>
          <div className="form-container">
            <h2>New Journal</h2>
            <form onSubmit={handleCreateJournal}>
              <input
                type="text"
                placeholder="Title"
                value={journalForm.title}
                onChange={(e) => setJournalForm({ ...journalForm, title: e.target.value })}
                required
                style={{ width: '100%', padding: '0.8rem', marginBottom: '1rem', borderRadius: '10px', border: '1px solid #ddd' }}
              />
              <textarea
                placeholder="Content"
                value={journalForm.content}
                onChange={(e) => setJournalForm({ ...journalForm, content: e.target.value })}
                rows="8"
                required
                style={{ width: '100%', padding: '0.8rem', marginBottom: '1rem', borderRadius: '10px', border: '1px solid #ddd' }}
              />
              <label>
                <input
                  type="checkbox"
                  checked={journalForm.is_public}
                  onChange={(e) => setJournalForm({ ...journalForm, is_public: e.target.checked })}
                />
                {' '}Make public
              </label>
              <button type="submit" className="submit-btn">Create</button>
              <button type="button" onClick={() => setShowForm(false)} className="submit-btn" style={{ background: '#ccc', marginTop: '0.5rem' }}>
                Cancel
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default MyProfile;
